function parseJson(value, label) {
  if (value && typeof value === 'object' && !Array.isArray(value)) return value;
  const text = String(value ?? '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '');
  try {
    const parsed = JSON.parse(text);
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new Error('不是对象');
    return parsed;
  } catch {
    throw new Error(`${label} 必须返回有效 JSON 对象。`);
  }
}
const keep = (value) => typeof value === 'string' ? value.trim() : (value ?? null);
const list = (value, max) => (Array.isArray(value) ? value : [])
  .map(keep)
  .filter((item) => item !== null && item !== '')
  .slice(0, max);
const product = parseJson($('Product Experience Agent').first().json.output, 'Product Experience Agent');
const architecture = parseJson($('Data Security Architect Agent').first().json.output, 'Data Security Architect Agent');
const requestedFeature = String($('When chat message received').first().json.chatInput || '在平台侧边栏新增 Codex Runs 入口，只读可视化展示 C:\\Users\\XuperMan\\.n8n\\database.sqlite 中的 Codex Coding Agent 运行记录。').trim();
return [{ json: {
  requestedFeature,
  productDesign: {
    userExperience: keep(product.userExperience),
    sidebarEntry: keep(product.sidebarEntry),
    pageSections: list(product.pageSections, 3),
    visibleFields: list(product.visibleFields, 6),
    filters: list(product.filters, 1),
    acceptanceCriteria: list(product.acceptanceCriteria, 4),
    risks: list(product.risks, 2),
  },
  architectureDesign: {
    dataSource: keep(architecture.dataSource),
    existingComponentsToReuse: list(architecture.existingComponentsToReuse, 4),
    backendChanges: list(architecture.backendChanges, 2),
    apiContract: keep(architecture.apiContract),
    permissions: keep(architecture.permissions),
    sqliteNotes: keep(architecture.sqliteNotes),
    tests: list(architecture.tests, 3),
    constraints: list(architecture.constraints, 3),
    risks: list(architecture.risks, 2),
  },
  requiredVerificationProfile: 'codex-runs-sidebar-targeted'
} }];

function parseJson(value) {
  if (value && typeof value === 'object' && !Array.isArray(value)) return value;
  const text = String(value ?? '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '');
  const parsed = JSON.parse(text);
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new Error('规划 Agent 必须返回 JSON 对象。');
  return parsed;
}
const text = (value) => String(value ?? '').trim();
const list = (value, max) => (Array.isArray(value) ? value : [])
  .map(text).filter(Boolean).slice(0, max);
const raw = parseJson($json.output);
const plan = {
  version: 1,
  title: text(raw.title || 'Codex Runs 侧边栏最小实现'),
  goal: text(raw.goal),
  constraints: list(raw.constraints, 4),
  acceptanceCriteria: list(raw.acceptanceCriteria, 5),
  implementationTask: text(raw.implementationTask),
  verificationProfile: 'codex-runs-sidebar-targeted',
  reviewerInstructions: text(raw.reviewerInstructions),
  designSummary: {
    navigation: text(raw.designSummary?.navigation),
    data: text(raw.designSummary?.data),
    security: text(raw.designSummary?.security),
    tests: text(raw.designSummary?.tests),
  },
};
for (const key of ['goal', 'implementationTask', 'reviewerInstructions']) {
  if (!plan[key]) throw new Error(`规划方案缺少字段：${key}。`);
}
if (plan.constraints.length < 1) throw new Error('规划方案至少需要一条约束。');
if (plan.acceptanceCriteria.length < 1) throw new Error('规划方案至少需要一条验收标准。');
const numbered = (items) => items.map((item, index) => `${index + 1}. ${item}`).join('\n');
const planSummary = [
  `方案：${plan.title}`,
  `目标：${plan.goal}`,
  `约束（${plan.constraints.length} 条）：\n${numbered(plan.constraints)}`,
  `验收标准（${plan.acceptanceCriteria.length} 条）：\n${numbered(plan.acceptanceCriteria)}`,
  `实现范围：${plan.designSummary.navigation || '侧边栏入口与页面'}；${plan.designSummary.data || '复用现有数据接口'}`,
].join('\n\n');
return [{ json: { plan, planSummary } }];

const requestedChanges = String($json.chatInput ?? '').trim();
if (!requestedChanges) throw new Error('修改意见不能为空。Codex 尚未运行。');
const currentPlan = $('Normalize Goal Plan').last().json.plan;
return [{ json: {
  currentPlan,
  requestedChanges,
  limits: {
    constraints: '最多 4 条',
    acceptanceCriteria: '最多 5 条',
    implementationTask: '最多 700 个中文字符',
    scope: '只修改用户指出的内容，不增加新功能',
  },
} }];

const approvedSpecification = $('Normalize Goal Plan').last().json.plan;
const requiredString = ['goal', 'implementationTask', 'reviewerInstructions', 'verificationProfile'];
for (const key of requiredString) {
  if (typeof approvedSpecification[key] !== 'string' || !approvedSpecification[key].trim()) throw new Error(`已批准方案缺少字段：${key}。`);
}
if (!Array.isArray(approvedSpecification.constraints) || approvedSpecification.constraints.length === 0) throw new Error('已批准方案必须包含 constraints。');
if (!Array.isArray(approvedSpecification.acceptanceCriteria) || approvedSpecification.acceptanceCriteria.length === 0) throw new Error('已批准方案必须包含 acceptanceCriteria。');
if (approvedSpecification.verificationProfile !== 'codex-runs-sidebar-targeted') throw new Error('verificationProfile 必须保持为 codex-runs-sidebar-targeted。');
let mode = 'approved-as-proposed';
try {
  if ($('Revise Goal Specification Agent').last().json.output) mode = 'approved-after-revision';
} catch {}
return [{ json: { approvedSpecification, approval: { mode, confirmedAt: new Date().toISOString() } } }];

const codex = $('Codex Coding Agent').item.json;
let reviewer;
try {
  const text = String($json.output ?? '').replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '');
  reviewer = JSON.parse(text);
} catch {
  reviewer = { score: 0, verdict: 'blocked', summary: 'Reviewer did not return valid JSON.', issues: [{ id: 'review-json', severity: 'error', message: 'Reviewer output is unavailable or invalid.' }] };
}
return [{ json: { artifact: codex.artifact, checks: codex.checks, reviewer, extraContext: { codexRunId: codex.codexCoding.runId, threadId: codex.codexCoding.threadId, turnId: codex.codexCoding.turnId, summary: codex.codexCoding.summary, approvedSpecification: $('Finalize Approved Goal Plan').item.json.approvedSpecification } } }];

